const getPincodesForLocation = (loc: string): string[] => {
  if (!loc) return [];
  // Try exact match first
  if (DISTRICT_PINCODES[loc]) return DISTRICT_PINCODES[loc];
  // Try partial match (e.g. "Hyderabad, Telangana" -> "Hyderabad")
  const key = Object.keys(DISTRICT_PINCODES).find(k => loc.startsWith(k) || loc.includes(k));
  return key ? DISTRICT_PINCODES[key] : [];
};

// JOB_CATEGORIES now loaded dynamically from Firestore via useJobCategories hook

